"""
Automated Schema Healer for Molavi Web Intelligence Engine (MWIE).
Detects JSON-LD and Knowledge Graph gaps and synthesizes a unified Schema.org @graph block.
"""

import json
import re
from typing import Any
from urllib.parse import urljoin, urlparse

from bs4 import BeautifulSoup

from mwie.core.models import GEOReport, SchemaGapReport, TechnicalSEOReport

ATTRIBUTION_COMMENT = (
    "// Generated by Molavi Web Intelligence Engine (MWIE) | molavi.pro | InTen Agency (inten.asia)"
)

AUTHORITATIVE_SAME_AS_DOMAINS = (
    "wikidata.org",
    "linkedin.com",
    "github.com",
)

EXTENDED_AUTHORITY_DOMAINS = (
    "wikidata.org",
    "wikipedia.org",
    "linkedin.com",
    "github.com",
    "x.com",
    "twitter.com",
    "youtube.com",
)

ORGANIZATION_TYPES = {
    "Organization",
    "Corporation",
    "EducationalOrganization",
    "GovernmentOrganization",
    "LocalBusiness",
    "NGO",
    "NewsMediaOrganization",
    "ProfessionalService",
}

ARTICLE_PATH_SEGMENTS = ("/blog", "/notes", "/research", "/article", "/articles", "/news", "/post")


def _normalize_types(raw_type: Any) -> list[str]:
    if isinstance(raw_type, list):
        return [str(item) for item in raw_type if item]
    if raw_type:
        return [str(raw_type)]
    return []


def _normalize_same_as(raw_same_as: Any) -> list[str]:
    if isinstance(raw_same_as, str) and raw_same_as.strip():
        return [raw_same_as.strip()]
    if isinstance(raw_same_as, list):
        return [str(item).strip() for item in raw_same_as if isinstance(item, str) and item.strip()]
    return []


def _extract_logo_url(logo_val: Any, origin: str) -> str | None:
    if isinstance(logo_val, str) and logo_val.strip():
        return urljoin(origin, logo_val.strip())
    if isinstance(logo_val, dict):
        candidate = logo_val.get("url") or logo_val.get("contentUrl")
        if isinstance(candidate, str) and candidate.strip():
            return urljoin(origin, candidate.strip())
    return None


class SchemaHealer:
    """Detects Knowledge Graph / JSON-LD gaps and synthesizes a unified Schema.org @graph."""

    def __init__(
        self,
        raw_html: str,
        url: str,
        seo_report: TechnicalSEOReport | None = None,
        geo_report: GEOReport | None = None,
    ):
        self.raw_html = raw_html or ""
        self.url = url
        self.seo_report = seo_report
        self.geo_report = geo_report
        self.soup = BeautifulSoup(self.raw_html, "html.parser")

        parsed = urlparse(url)
        scheme = parsed.scheme or "https"
        netloc = parsed.netloc or "example.com"
        self.origin = f"{scheme}://{netloc}"
        self.hostname = netloc.lower().removeprefix("www.")
        self.path = parsed.path or "/"

        self.raw_blocks = self._extract_raw_json_ld_blocks()
        self.nodes = self._collect_all_nodes(self.raw_blocks)

    def _extract_raw_json_ld_blocks(self) -> list[Any]:
        blocks: list[Any] = []
        for script in self.soup.find_all(
            "script", attrs={"type": lambda t: t and "ld+json" in t.lower()}
        ):
            content = script.string or script.get_text()
            if not content or not content.strip():
                continue
            try:
                parsed = json.loads(content.strip())
                blocks.append(parsed)
            except Exception:
                continue
        return blocks

    def _collect_all_nodes(self, blocks: list[Any]) -> list[dict[str, Any]]:
        nodes: list[dict[str, Any]] = []

        def _visit(item: Any) -> None:
            if isinstance(item, list):
                for sub in item:
                    _visit(sub)
                return
            if not isinstance(item, dict):
                return
            if "@graph" in item and isinstance(item["@graph"], list):
                for g_node in item["@graph"]:
                    _visit(g_node)
            if "@type" in item or "@id" in item:
                nodes.append(item)
            for key in ("author", "founder", "publisher", "provider", "mainEntity"):
                nested = item.get(key)
                if isinstance(nested, (dict, list)):
                    _visit(nested)

        for block in blocks:
            _visit(block)
        return nodes

    def _discover_html_authority_links(self) -> list[str]:
        links: list[str] = []
        seen: set[str] = set()
        for a_tag in self.soup.find_all("a", href=True):
            href = a_tag["href"].strip()
            if not href.startswith(("http://", "https://")):
                continue
            host = urlparse(href).netloc.lower()
            if any(domain in host for domain in EXTENDED_AUTHORITY_DOMAINS):
                if href not in seen:
                    seen.add(href)
                    links.append(href)
        return links

    def _collect_json_ld_same_as(self) -> list[str]:
        urls: list[str] = []
        seen: set[str] = set()
        for node in self.nodes:
            for link in _normalize_same_as(node.get("sameAs")):
                if link not in seen:
                    seen.add(link)
                    urls.append(link)
        return urls

    def detect_gaps(self) -> SchemaGapReport:
        """Evaluate existing JSON-LD blocks against unified Knowledge Graph criteria."""
        has_unified_graph = any(
            isinstance(block, dict)
            and isinstance(block.get("@graph"), list)
            and len(block["@graph"]) >= 2
            for block in self.raw_blocks
        )

        person_nodes = [n for n in self.nodes if "Person" in _normalize_types(n.get("@type"))]
        has_anchored_person = any(
            isinstance(p.get("@id"), str)
            and bool(p["@id"].strip())
            and isinstance(p.get("name"), str)
            and bool(p["name"].strip())
            for p in person_nodes
        )

        json_ld_same_as = self._collect_json_ld_same_as()
        has_authoritative_same_as = any(
            any(domain in urlparse(link).netloc.lower() for domain in AUTHORITATIVE_SAME_AS_DOMAINS)
            for link in json_ld_same_as
        )

        has_in_language = any(
            bool(node.get("inLanguage"))
            for node in self.nodes
            if isinstance(node.get("inLanguage"), (str, list))
        )

        org_nodes = [
            n
            for n in self.nodes
            if any(t in ORGANIZATION_TYPES for t in _normalize_types(n.get("@type")))
        ]
        has_valid_organization = any(
            isinstance(org.get("@id"), str)
            and bool(org["@id"].strip())
            and isinstance(org.get("name"), str)
            and bool(org["name"].strip())
            and isinstance(org.get("url"), str)
            and bool(org["url"].strip())
            and bool(org.get("logo") or org.get("image"))
            for org in org_nodes
        )

        website_nodes = [n for n in self.nodes if "WebSite" in _normalize_types(n.get("@type"))]
        has_valid_website = any(
            isinstance(site.get("@id"), str)
            and bool(site["@id"].strip())
            and isinstance(site.get("name"), str)
            and bool(site["name"].strip())
            and isinstance(site.get("url"), str)
            and bool(site["url"].strip())
            for site in website_nodes
        )

        detected_gaps: list[str] = []
        if not has_unified_graph:
            detected_gaps.append(
                "Lack of a unified Schema.org @graph array connecting domain entities."
            )
        if not has_anchored_person:
            detected_gaps.append(
                "Missing or unanchored Person (Founder/Author) entity with a canonical @id."
            )
        if not has_authoritative_same_as:
            detected_gaps.append(
                "Absence of authoritative sameAs links (Wikidata, LinkedIn, GitHub)."
            )
        if not has_in_language:
            detected_gaps.append(
                "Missing inLanguage parameter on core WebSite / Service / Organization nodes."
            )
        if not has_valid_organization:
            detected_gaps.append(
                "Missing or incomplete Organization parameters (@id, name, url, logo, founder)."
            )
        if not has_valid_website:
            detected_gaps.append(
                "Missing or incomplete WebSite schema (@id, name, url, publisher)."
            )

        needs_healing = len(detected_gaps) > 0
        return SchemaGapReport(
            is_healthy=not needs_healing,
            needs_healing=needs_healing,
            has_unified_graph=has_unified_graph,
            has_anchored_person=has_anchored_person,
            has_authoritative_same_as=has_authoritative_same_as,
            has_in_language=has_in_language,
            has_valid_organization=has_valid_organization,
            has_valid_website=has_valid_website,
            detected_gaps=detected_gaps,
            discovered_same_as=json_ld_same_as,
        )

    def _infer_language(self) -> str:
        html_tag = self.soup.find("html")
        if html_tag and html_tag.get("lang"):
            return str(html_tag["lang"]).strip()
        og_locale = self.soup.find("meta", property="og:locale")
        if og_locale and og_locale.get("content"):
            return str(og_locale["content"]).strip().replace("_", "-")
        return "en"

    def _infer_site_and_org_name(self) -> str:
        for node in self.nodes:
            types = _normalize_types(node.get("@type"))
            if any(t in ORGANIZATION_TYPES or t == "WebSite" for t in types):
                name = node.get("name")
                if isinstance(name, str) and name.strip():
                    return name.strip()

        og_site = self.soup.find("meta", property="og:site_name")
        if og_site and og_site.get("content"):
            return str(og_site["content"]).strip()

        if self.geo_report and self.geo_report.primary_brand:
            return self.geo_report.primary_brand

        title_tag = self.soup.find("title")
        if title_tag and title_tag.get_text(strip=True):
            raw_title = title_tag.get_text(strip=True)
            for sep in ("|", "—", "–", " - "):
                if sep in raw_title:
                    candidate = raw_title.split(sep)[-1].strip()
                    if 2 <= len(candidate) <= 60:
                        return candidate
            return raw_title[:60]

        base = self.hostname.split(".")[0]
        return base.capitalize() if base else "Brand"

    def _infer_description(self, site_name: str) -> str:
        if self.seo_report and self.seo_report.meta_description:
            return self.seo_report.meta_description
        desc_tag = self.soup.find("meta", attrs={"name": "description"})
        if desc_tag and desc_tag.get("content"):
            return str(desc_tag["content"]).strip()
        og_desc = self.soup.find("meta", property="og:description")
        if og_desc and og_desc.get("content"):
            return str(og_desc["content"]).strip()
        return f"Official digital presence, services, and knowledge platform for {site_name}."

    def _infer_logo_url(self) -> str:
        for node in self.nodes:
            if any(t in ORGANIZATION_TYPES for t in _normalize_types(node.get("@type"))):
                logo = _extract_logo_url(node.get("logo") or node.get("image"), self.origin)
                if logo:
                    return logo

        og_image = self.soup.find("meta", property="og:image")
        if og_image and og_image.get("content"):
            return urljoin(self.origin, str(og_image["content"]).strip())

        icon = self.soup.find("link", rel=lambda r: r and "icon" in " ".join(r).lower())
        if icon and icon.get("href"):
            return urljoin(self.origin, str(icon["href"]).strip())

        return f"{self.origin}/logo.png"

    def _infer_founder_name(self, site_name: str) -> str:
        for node in self.nodes:
            if "Person" in _normalize_types(node.get("@type")):
                name = node.get("name")
                if isinstance(name, str) and name.strip():
                    return name.strip()

        author_meta = self.soup.find("meta", attrs={"name": "author"})
        if author_meta and author_meta.get("content"):
            return str(author_meta["content"]).strip()

        if self.geo_report:
            for ent in self.geo_report.entities:
                if ent.entity_type == "Person" and ent.name.strip():
                    return ent.name.strip()

        return f"Founder of {site_name}"

    def _infer_same_as_links(self) -> list[str]:
        merged: list[str] = []
        seen: set[str] = set()
        for url in self._collect_json_ld_same_as() + self._discover_html_authority_links():
            if url not in seen:
                seen.add(url)
                merged.append(url)

        slug = re.sub(r"[^a-z0-9-]", "", self.hostname.split(".")[0]) or "brand"
        defaults = [
            ("wikidata.org", f"https://www.wikidata.org/wiki/Special:Search?search={slug}"),
            ("linkedin.com", f"https://www.linkedin.com/company/{slug}"),
            ("github.com", f"https://github.com/{slug}"),
        ]
        for domain, fallback in defaults:
            if not any(domain in urlparse(link).netloc.lower() for link in merged):
                merged.append(fallback)
        return merged

    def _infer_primary_service(self, site_name: str, description: str) -> tuple[str, str]:
        h1 = self.soup.find("h1")
        h1_text = h1.get_text(" ", strip=True) if h1 else ""
        if h1_text and 4 <= len(h1_text) <= 90:
            service_name = h1_text
        elif self.seo_report and self.seo_report.meta_title:
            service_name = self.seo_report.meta_title[:90]
        else:
            service_name = f"{site_name} Core Solutions & Services"

        service_type = f"{site_name} Digital & Domain Services"
        return service_name, service_type

    def _is_article_page(self) -> bool:
        og_type = self.soup.find("meta", property="og:type")
        if og_type and str(og_type.get("content", "")).lower().strip() == "article":
            return True
        lower_path = self.path.lower()
        return any(seg in lower_path for seg in ARTICLE_PATH_SEGMENTS)

    def synthesize_graph(self) -> dict[str, Any]:
        """Build a standardized, connected Schema.org JSON-LD @graph dictionary."""
        in_language = self._infer_language()
        site_name = self._infer_site_and_org_name()
        description = self._infer_description(site_name)
        logo_url = self._infer_logo_url()
        founder_name = self._infer_founder_name(site_name)
        same_as_links = self._infer_same_as_links()
        service_name, service_type = self._infer_primary_service(site_name, description)

        website_id = f"{self.origin}/#website"
        org_id = f"{self.origin}/#organization"
        person_id = f"{self.origin}/#person"
        service_id = f"{self.origin}/#service"
        logo_id = f"{self.origin}/#logo"

        person_same_as = [
            link
            for link in same_as_links
            if any(d in urlparse(link).netloc.lower() for d in AUTHORITATIVE_SAME_AS_DOMAINS)
        ]

        website_node: dict[str, Any] = {
            "@type": "WebSite",
            "@id": website_id,
            "url": f"{self.origin}/",
            "name": site_name,
            "description": description,
            "inLanguage": in_language,
            "publisher": {"@id": org_id},
            "potentialAction": {
                "@type": "SearchAction",
                "target": {
                    "@type": "EntryPoint",
                    "urlTemplate": f"{self.origin}/?s={{search_term_string}}",
                },
                "query-input": "required name=search_term_string",
            },
        }

        organization_node: dict[str, Any] = {
            "@type": "Organization",
            "@id": org_id,
            "name": site_name,
            "url": f"{self.origin}/",
            "description": description,
            "inLanguage": in_language,
            "logo": {
                "@type": "ImageObject",
                "@id": logo_id,
                "url": logo_url,
                "contentUrl": logo_url,
                "caption": site_name,
            },
            "founder": {"@id": person_id},
            "sameAs": same_as_links,
        }

        person_node: dict[str, Any] = {
            "@type": "Person",
            "@id": person_id,
            "name": founder_name,
            "jobTitle": "Founder",
            "url": f"{self.origin}/",
            "worksFor": {"@id": org_id},
            "sameAs": person_same_as,
        }

        service_node: dict[str, Any] = {
            "@type": "Service",
            "@id": service_id,
            "name": service_name,
            "description": description,
            "serviceType": service_type,
            "provider": {"@id": org_id},
            "areaServed": "Global",
            "inLanguage": in_language,
            "url": self.url,
        }

        graph: list[dict[str, Any]] = [
            website_node,
            organization_node,
            person_node,
            service_node,
        ]

        if self._is_article_page():
            article_node: dict[str, Any] = {
                "@type": "Article",
                "@id": f"{self.url}#article",
                "headline": service_name,
                "description": description,
                "url": self.url,
                "inLanguage": in_language,
                "author": {"@id": person_id},
                "publisher": {"@id": org_id},
                "isPartOf": {"@id": website_id},
                "mainEntityOfPage": self.url,
            }
            graph.append(article_node)

        return {
            "@context": "https://schema.org",
            "@graph": graph,
        }

    def heal(self) -> tuple[SchemaGapReport, str]:
        """Run gap detection and synthesize the attribution-tagged JSON-LD @graph string."""
        gap_report = self.detect_gaps()
        graph_payload = self.synthesize_graph()
        healed_str = (
            f"{ATTRIBUTION_COMMENT}\n{json.dumps(graph_payload, indent=2, ensure_ascii=False)}"
        )
        return gap_report, healed_str
